// Usage: node split-pack.mjs <repoRoot> <packId>
// Moves a local pack's manifest-listed rule modules into worldRules/ and workRules/,
// rewrites every relative import that reaches a moved file (or leaves one), and
// replaces pack.mjs with a pack.json holding only what the directory cannot say.
import { readFileSync, writeFileSync, existsSync, readdirSync, mkdirSync, statSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join, dirname, relative, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const [root, id] = process.argv.slice(2);
const packRel = `.claudinite/local/packs/${id}`;
const packDir = join(root, packRel);
const manifestPath = join(packDir, 'pack.mjs');
const source = readFileSync(manifestPath, 'utf8');
const manifest = (await import(pathToFileURL(manifestPath).href)).default;

const imports = new Map([...source.matchAll(/^import\s+(\w+)\s+from\s+['"](\.\/[^'"]+)['"];?$/gm)].map((m) => [m[1], m[2].slice(2)]));
const moves = new Map(); // old abs -> new abs
for (const scope of ['worldRules', 'workRules']) {
  const body = new RegExp(`${scope}:\\s*\\[([^\\]]*)\\]`).exec(source)?.[1] ?? '';
  for (const ident of body.split(',').map((s) => s.trim()).filter(Boolean)) {
    const file = imports.get(ident);
    if (!file) throw new Error(`${scope} names ${ident}, which no sibling import binds`);
    moves.set(join(packDir, file), join(packDir, scope, file));
  }
}
const listed = [...moves.keys()].length;
if (listed !== (manifest.worldRules?.length ?? 0) + (manifest.workRules?.length ?? 0)) throw new Error('rule count mismatch between source scan and evaluated manifest');

// Every tracked module outside the mount, read before anything moves.
const tracked = execFileSync('git', ['ls-files', '-z'], { cwd: root, encoding: 'utf8' }).split('\0')
  .filter((f) => /\.(mjs|js|cjs)$/.test(f) && !f.startsWith('.claudinite/shared/') && !f.includes('node_modules/'));
const texts = new Map(tracked.map((f) => [join(root, f), readFileSync(join(root, f), 'utf8')]));

const where = (abs) => moves.get(abs) ?? abs;
const spec = (fromFile, toAbs) => { let r = relative(dirname(fromFile), toAbs); if (!r.startsWith('.')) r = `./${r}`; return r; };
const SPEC = /((?:^|\n)\s*(?:import|export)\b[^'"\n]*?from\s*|\bimport\s*\(\s*|^\s*import\s+)(['"])(\.{1,2}\/[^'"]+)\2/g;
const rewritten = [];
for (const [abs, text] of texts) {
  if (abs === manifestPath) continue;
  const newAbs = where(abs);
  let changed = false;
  const out = text.replace(SPEC, (all, lead, q, s) => {
    const target = resolve(dirname(abs), s);
    const next = spec(newAbs, where(target));
    if (next === s) return all;
    changed = true;
    return `${lead}${q}${next}${q}`;
  });
  if (changed) { writeFileSync(abs, out); rewritten.push(relative(root, abs)); }
}
for (const [from, to] of moves) {
  mkdirSync(dirname(to), { recursive: true });
  execFileSync('git', ['mv', relative(root, from), relative(root, to)], { cwd: root });
}

// The manifest: drop what the directory already says and what is retired.
const skillDirs = existsSync(join(packDir, 'skills'))
  ? readdirSync(join(packDir, 'skills')).filter((d) => statSync(join(packDir, 'skills', d)).isDirectory()).sort() : [];
const dropped = [];
const json = {};
for (const [key, value] of Object.entries(manifest)) {
  const same =
    (key === 'id' && value === id) || (key === 'prose' && value === 'RULES.md') ||
    key === 'detect' || key === 'marker' || key === 'version' || key === 'worldRules' || key === 'workRules' ||
    (key === 'skills' && JSON.stringify([...value].sort()) === JSON.stringify(skillDirs));
  if (same) dropped.push(key); else json[key] = value;
}
writeFileSync(join(packDir, 'pack.json'), `${JSON.stringify(json, null, 2)}\n`);
execFileSync('git', ['rm', '-q', relative(root, manifestPath)], { cwd: root });
execFileSync('git', ['add', relative(root, join(packDir, 'pack.json')), ...rewritten], { cwd: root });
console.log(JSON.stringify({ moved: [...moves.values()].map((p) => relative(packDir, p)), rewritten, dropped, kept: Object.keys(json) }, null, 1));
EOF
