// canary work rule — a session that edits the canary pack must leave it loadable.
//
// Work scope, so it judges the change in front of the session (the Stop hook),
// not the repo at rest: it only looks when the branch actually touched the pack
// directory. A session that never goes near it is never asked about it.
//
// Like its world-scope sibling this is a liveness probe with a real edge case
// attached — deleting `pack.mjs` or `RULES.md` while keeping the `local/canary`
// declaration turns every later session into a blocking `config` error at load,
// which is the least debuggable way for this repo to break. In normal operation
// it never fires; its job is to prove work-scope dispatch reached a local pack.
//
// Dependency-free by the same rule as the world-scope module: plain finding
// objects, no imports out of `.claudinite/shared/`.
const id = 'canary/pack-intact';
const severity = 'blocking';
const doc = '.claudinite/local/packs/canary/RULES.md';
const why =
  'the declaration names local/canary — if the manifest or its prose goes missing the pack ' +
  'loader raises a blocking config error on every later session, in this repo and in every rehearsal of it';

const DIR = '.claudinite/local/packs/canary/';
const REQUIRED = [`${DIR}pack.mjs`, `${DIR}RULES.md`];

export default {
  id,
  severity,
  description: 'a change touching the canary pack leaves its manifest and prose in place',
  doc,
  why,
  scope: 'work',

  run(work) {
    if (!work.changedFiles.some((f) => f.startsWith(DIR))) return [];
    return REQUIRED.filter((f) => !work.exists(f)).map((file) => ({
      rule: id,
      severity,
      file,
      line: null,
      what: `${file} is gone, but .claudinite-settings.json still declares local/canary`,
      why,
      fix: `restore ${file}, or drop "local/canary" from the "packs" list in .claudinite-settings.json`,
      doc,
    }));
  },
};
====
# Canary rules

This repo is the **live canary** for Claudinite's consumer-safety gate. It is not a product. It
carries no application code and it is meant to be disposable.

The canon's `canary-rehearsal.yml` workflow converges this repo against a candidate canon ref and
asks one question: *does a real member still work?* Everything here exists to make that question
answerable.

## Standing rules

- **Stay a realistic member.** The value of a canary is that it is real. Keep the vendored mount at
  `.claudinite/shared/`, the declaration, the hooks, the scheduler workflow, the conformance
  workflow, and this local pack. A stub proves nothing. (stay-realistic-member)
- **Keep the local pack loading.** `local/canary` is declared in `.claudinite-settings.json`. It
  must keep a valid `pack.mjs`, a rule in each scope, at least one bundled skill, and this file.
  (keep-local-pack)
- **The canary's own rules stay trivial.** They prove the pack loaded; they do not enforce anything
  about this repo. A rule with real opinions would turn the canary red for reasons unrelated to the
  canon ref under test, which destroys the only signal this repo produces. (canarys-rules-stay)
- **Divergence from `main` is expected and disposable.** A rehearsal may leave this repo converged
  against a candidate ref. Re-baselining it to canon `main` is always the right repair; there is no
  local state here worth preserving. (divergence-main-expected)
====
import { test } from 'node:test';
import assert from 'node:assert/strict';
import rule from './pack-shape.mjs';

const PACK_FILE = '.claudinite/local/packs/canary/pack.mjs';
const SKILL_FILE = '.claudinite/local/packs/canary/skills/canary-role/SKILL.md';

const CLEAN_TEXT = `
export default {
  id: 'canary',
  worldRules: [mountPresent],
  workRules: [packIntact],
  skills: ['canary-role'],
};
`;

function fakeCtx({ text = CLEAN_TEXT, skillExists = true } = {}) {
  return {
    read: (path) => (path === PACK_FILE ? text : null),
    exists: (path) => (path === SKILL_FILE ? skillExists : false),
  };
}

test('missing pack.mjs is left to pack-intact.mjs', () => {
  const findings = rule.run({ read: () => null, exists: () => false });
  assert.deepEqual(findings, []);
});

test('fires when worldRules is empty', () => {
  const text = CLEAN_TEXT.replace('worldRules: [mountPresent]', 'worldRules: []');
  const findings = rule.run(fakeCtx({ text }));
  assert.ok(findings.some((f) => /no worldRules/.test(f.what)));
});

test('fires when workRules is empty', () => {
  const text = CLEAN_TEXT.replace('workRules: [packIntact]', 'workRules: []');
  const findings = rule.run(fakeCtx({ text }));
  assert.ok(findings.some((f) => /no workRules/.test(f.what)));
});

test('fires when skills is empty', () => {
  const text = CLEAN_TEXT.replace("skills: ['canary-role']", 'skills: []');
  const findings = rule.run(fakeCtx({ text }));
  assert.ok(findings.some((f) => /no bundled skills/.test(f.what)));
});

test('fires when a declared skill has no SKILL.md on disk', () => {
  const findings = rule.run(fakeCtx({ skillExists: false }));
  assert.ok(findings.some((f) => /canary-role.*missing/.test(f.what)));
});

test('stays quiet when the manifest and every skill file agree', () => {
  const findings = rule.run(fakeCtx());
  assert.deepEqual(findings, []);
});
